using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using System.Linq;
public static class CymbalCandidateSetup{public static void Run(){EditorSceneManager.OpenScene("Assets/MusicRoom.unity");var drum=Object.FindObjectsByType<DrumSound>(FindObjectsInactive.Include,FindObjectsSortMode.None).First(d=>d.name=="CymbalHitZone");Object.DestroyImmediate(drum.GetComponent<BoxCollider>());var c=drum.gameObject.AddComponent<MeshCollider>();c.sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Physics/CymbalContactMesh.asset");c.convex=true;c.isTrigger=true;Physics.SyncTransforms();
for(int i=0;i<8;i++){float a=i*Mathf.PI/4;Vector3 radial=drum.transform.right*Mathf.Cos(a)+drum.transform.up*Mathf.Sin(a);var ray=new Ray(drum.transform.position+radial*.20f+drum.transform.forward*.15f,-drum.transform.forward);if(!c.Raycast(ray,out var hit,.3f))throw new System.Exception("No playable surface at ring sample "+i);var sphereGo=new GameObject("contact test");var sphere=sphereGo.AddComponent<SphereCollider>();sphere.radius=.012f;bool contact=Physics.ComputePenetration(sphere,hit.point+drum.transform.forward*.0108f,Quaternion.identity,c,drum.transform.position,drum.transform.rotation,out _,out _);if(!contact)throw new System.Exception("No mesh contact at ring sample "+i);bool outside=Physics.ComputePenetration(sphere,drum.transform.position+radial*.29f,Quaternion.identity,c,drum.transform.position,drum.transform.rotation,out _,out _);if(outside)throw new System.Exception("Collider outside cymbal "+i);Object.DestroyImmediate(sphereGo);}
Debug.Log("CYMBAL_CANDIDATE eight surface contacts passed; eight outside-disc contacts rejected");EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),"Assets/CymbalColliderCandidate.unity");EditorApplication.Exit(0);}}
